begin;
create table public.assisted_sync_sessions(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,financial_connection_id uuid not null,provider text not null,status text not null check(status in('draft','awaiting_consent','connecting','discovering_accounts','selecting_accounts','ready','importing','paused','retrying','processing','comparing','awaiting_review','partially_confirmed','confirmed','completed','failed','cancelled')),environment text not null check(environment in('mock','sandbox','production')),window_start timestamptz not null,window_end timestamptz not null,timezone text not null default 'America/Sao_Paulo',selected_account_ids jsonb not null default '[]',requested_scopes jsonb not null default '[]',current_step text not null default 'institution',started_at timestamptz,paused_at timestamptz,resumed_at timestamptz,finished_at timestamptz,failure_code text,failure_message_redacted text,configuration jsonb not null default '{"reviewRequired":true,"automaticPublish":false}',statistics jsonb not null default '{}',lock_version bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,id),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id),check(window_end>=window_start),check(window_end-window_start<=interval '30 days' or (configuration->>'historicalExpansionApproved')::boolean is true));
create unique index assisted_sync_one_active_connection_idx on public.assisted_sync_sessions(user_id,financial_connection_id) where status not in('completed','failed','cancelled');
create table public.sync_runs(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,assisted_sync_session_id uuid not null,financial_connection_id uuid not null,external_account_id uuid,resource_type text not null check(resource_type in('accounts','balances','transactions')),status text not null check(status in('pending','running','paused','retrying','completed','failed','cancelled')),cursor text,page_number integer not null default 0,window_start timestamptz not null,window_end timestamptz not null,items_received bigint not null default 0,items_created bigint not null default 0,items_updated bigint not null default 0,items_skipped bigint not null default 0,items_failed bigint not null default 0,started_at timestamptz,last_checkpoint_at timestamptz,finished_at timestamptz,error_summary jsonb not null default '{}',lock_version bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,id),foreign key(user_id,assisted_sync_session_id) references public.assisted_sync_sessions(user_id,id),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id),foreign key(user_id,external_account_id) references public.external_accounts(user_id,id));
create unique index sync_runs_active_scope_idx on public.sync_runs(user_id,financial_connection_id,coalesce(external_account_id,'00000000-0000-0000-0000-000000000000'),resource_type,window_start,window_end) where status in('pending','running','paused','retrying');
create table public.sync_checkpoints(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,sync_run_id uuid not null,financial_connection_id uuid not null,external_account_id uuid,resource_type text not null,cursor text,page_number integer not null,last_item_key text,provider_checkpoint jsonb,processed_count bigint not null default 0,adapter_version text not null,created_at timestamptz not null default now(),unique(user_id,id),unique(user_id,sync_run_id,external_account_id,resource_type,page_number),foreign key(user_id,sync_run_id) references public.sync_runs(user_id,id),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id));
create table public.balance_observations(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,financial_connection_id uuid not null,external_account_id uuid not null,amount numeric(24,8) not null,currency text not null,balance_type text not null check(balance_type in('available','current','blocked','credit_limit','unknown')),observed_at timestamptz not null,provider_timestamp text,provider text not null,quality_status text not null check(quality_status in('good','acceptable','partial','poor','unknown')),metadata jsonb not null default '{}',created_at timestamptz not null default now(),unique(user_id,financial_connection_id,external_account_id,balance_type,observed_at,amount),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id),foreign key(user_id,external_account_id) references public.external_accounts(user_id,id));
create table public.sync_difference_reports(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,assisted_sync_session_id uuid not null,status text not null check(status in('generated','reviewed','confirmed')),period_start timestamptz not null,period_end timestamptz not null,external_totals jsonb not null default '{}',internal_totals jsonb not null default '{}',differences jsonb not null default '{}',unmatched_count bigint not null default 0,suggested_count bigint not null default 0,matched_count bigint not null default 0,conflict_count bigint not null default 0,pending_count bigint not null default 0,missing_external_count bigint not null default 0,missing_internal_count bigint not null default 0,quality jsonb not null default '{}',generated_at timestamptz not null,confirmed_at timestamptz,created_at timestamptz not null default now(),unique(user_id,id),foreign key(user_id,assisted_sync_session_id) references public.assisted_sync_sessions(user_id,id));
create table public.assisted_sync_decisions(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,assisted_sync_session_id uuid not null,raw_transaction_id uuid,decision text not null check(decision in('match','merge','keep_both','ignore_source','create_manual','keep_reviewing','mark_conflict','undo')),status text not null default 'active',idempotency_key text not null,payload jsonb not null default '{}',decided_by uuid not null,decided_at timestamptz not null default now(),reverted_at timestamptz,created_at timestamptz not null default now(),unique(user_id,id),unique(user_id,idempotency_key),foreign key(user_id,assisted_sync_session_id) references public.assisted_sync_sessions(user_id,id),foreign key(user_id,raw_transaction_id) references public.raw_transactions(user_id,id));
create index assisted_sync_review_idx on public.assisted_sync_sessions(user_id,status,updated_at desc);create index sync_runs_progress_idx on public.sync_runs(user_id,assisted_sync_session_id,status);create index checkpoints_resume_idx on public.sync_checkpoints(user_id,sync_run_id,page_number desc);create index balance_observations_compare_idx on public.balance_observations(user_id,external_account_id,observed_at desc);create index difference_reports_session_idx on public.sync_difference_reports(user_id,assisted_sync_session_id,generated_at desc);
insert into public.schema_versions(component,version,migration_name,checksum,metadata) values('open-finance-assisted-sync',1,'014_create_assisted_sync_schema','phase7-v1','{"phase":7,"pilotDays":30,"reviewRequired":true,"automaticPublish":false,"balancesAreObservations":true}'::jsonb) on conflict(component) do update set version=excluded.version,applied_at=now(),migration_name=excluded.migration_name,checksum=excluded.checksum,metadata=excluded.metadata;
commit;
